const BASE_SCORE = 1;
const POINTS_PER_TYPE = 2;
const FREE_TYPES = 3;
const NO_SPHINX_SCORE = 0;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return NO_SPHINX_SCORE;
  const extraTypes = Math.max(countNonSphinxTypes(army) - FREE_TYPES, 0);
  return BASE_SCORE + POINTS_PER_TYPE * extraTypes + (extraTypes ? 0 : 1);
};

